context_info = ()
for d in context:
    prompt = "You are given a document. Determine if it contains information about an artist matching all or most of these clues.\n\nClues to check:\n- Born between 1940 and 1944 inclusive (\"early 1940s\").\n- Began playing piano before age 5.\n- Began studies at the Paris Conservatoire at age >6 and <11.\n- Was a pupil of Alfred Cortot (the pianist famed for his trio with violinist Jacques Thibaud and cellist Pablo Casals).\n- Performed Mozart’s Concerto for Two Pianos (K.365), between ages >9 and <15, with the composer-pianist Wilhelm Kempff (who died May 23, 1991), at the Théâtre des Champs-Elysées, under a conductor born between 1900 and 1911 inclusive.\n\nIf the document mentions any artist(s) that match all or most of the clues, provide for each candidate:\n- Artist name\n- Birth date/year and how it fits the 1940–1944 window\n- Evidence that they began piano before age 5 (quote)\n- Evidence they began at the Paris Conservatoire age >6 and <11 (quote)\n- Evidence they studied with Alfred Cortot (quote)\n- Evidence of performing Mozart K.365 with Wilhelm Kempff at Théâtre des Champs-Elysées and the conductor’s name (quote); include any mention of the conductor’s birth year if present\n- The artist’s mother’s full name as written in the document (quote and extracted name)\n- Any other parental information if present (quotes)\n\nUse this exact format for any matches:\nBEGIN_MATCH\nArtist: <name>\nBirth: <details>\nPiano_before_5: <quote or NONE>\nConservatoire_7_to_10: <quote or NONE>\nPupil_of_Cortot: <quote or NONE>\nMozart_K365_with_Kempff_TCE_and_conductor_1900_1911: <quote or NONE>\nMother_full_name: <quote and extracted name or NONE>\nOther_notes: <any relevant quotes>\nEND_MATCH\n\nIf no relevant artist is present, reply exactly NO_MATCH.\n\nDocument:\nBEGIN_DOCUMENT\n" + d + "\nEND_DOCUMENT"
    result = llm_query(prompt)
    context_info = context_info + (result,)

aggregation_prompt = "You will be given extracted candidate matches from multiple documents. Your task:\n1) Identify the single artist that satisfies all the clues:\n   - Born 1940–1944 inclusive\n   - Began piano before age 5\n   - Entered the Paris Conservatoire at age >6 and <11\n   - Pupil of Alfred Cortot (from the Thibaud–Casals–Cortot trio)\n   - Performed Mozart’s Concerto for Two Pianos (K.365) between ages >9 and <15 with Wilhelm Kempff (d. May 23, 1991) at the Théâtre des Champs-Elysées, under a conductor born 1900–1911\n2) From the provided quotes, extract the artist’s mother’s full name exactly as given.\n3) Output ONLY the mother's full name and nothing else.\n\nHere are the candidate matches and quotes from the context:\n" + "\n\n".join(context_info) + "\n\nRemember: Output only the mother's full name, with exact spelling from the quotes."
final_answer = llm_query(aggregation_prompt)
return_result(final_answer)